import time
# ask for starting date
text = input("Input date (D MMM Y): ")
d, month, y = text.split()
d = int(d)
y = int(y)

# loop forever
while True:
    d = d + 1
    # check leap year
    if (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0):
        feb_days = 29
    else:
        feb_days = 28
    # days in each month
    if month == "Jan" or month == "Mar" or month == "May" or month == "Jul" or month == "Aug" or month == "Oct" or month == "Dec":
        max_days = 31
    elif month == "Apr" or month == "Jun" or month == "Sep" or month == "Nov":
        max_days = 30
    elif month == "Feb":
        max_days = feb_days
    # check if past end of month
    if d > max_days:
        d = 1
        # go to next month
        if month == "Jan":
            month = "Feb"
        elif month == "Feb":
            month = "Mar"
        elif month == "Mar":
            month = "Apr"
        elif month == "Apr":
            month = "May"
        elif month == "May":
            month = "Jun"
        elif month == "Jun":
            month = "Jul"
        elif month == "Jul":
            month = "Aug"
        elif month == "Aug":
            month = "Sep"
        elif month == "Sep":
            month = "Oct"
        elif month == "Oct":
            month = "Nov"
        elif month == "Nov":
            month = "Dec"
        elif month == "Dec":
            month = "Jan"
            y = y + 1
    # display date with 2-digit day
    print(str(d).zfill(2), month, y)
    time.sleep(0.2)

